<script lang="ts">
 import {onMount} from 'svelte';import App from './App.svelte';import {accountRequest,setAccount,applyTheme,type Account} from './accounts';
 let user:Account|null=null;let token='';let ready=false;let busy=false;let error='';let setup=false;let recovery=false;let name='';let password='';let confirm='';let code='';let invitation=false;
 async function state(){try{const data=await accountRequest('','auth/state');token=data.token;setup=data.setup;recovery=data.recovery;user=data.user;setAccount(user);if(user)applyTheme(user.theme);error='';}catch(e){error=e instanceof Error?e.message:'Serveur indisponible.';}finally{ready=true;}}
 async function submit(event:SubmitEvent){event.preventDefault();if(busy)return;if((setup||recovery||invitation)&&password!==confirm){error='Les deux mots de passe sont différents.';return}busy=true;error='';try{const data=await accountRequest(token,'auth/'+(invitation?'activate':setup?'setup':recovery?'recover':'login'),'POST',invitation?{code,password}:{name,password,code});password='';confirm='';code='';invitation=false;user=data.user;token=data.token;setAccount(user);if(user)applyTheme(user.theme);}catch(e){error=e instanceof Error?e.message:'Connexion impossible.';}finally{busy=false;}}
 async function logout(){busy=true;try{await accountRequest(token,'auth/logout','POST');user=null;setAccount(null);await state();}catch(e){error=e instanceof Error?e.message:'Déconnexion impossible.';}finally{busy=false;}}
 async function expired(){if(!user)return;user=null;setAccount(null);password='';confirm='';await state();error='Votre session a expiré ou ses permissions ont changé. Reconnectez-vous.';}
 onMount(()=>{const params=new URLSearchParams(location.hash.slice(1));const invite=params.get('invitation');if(invite){code=invite;invitation=true;history.replaceState(null,'',location.pathname+location.search)}
  const original=window.fetch;let handling=false;window.fetch=async(...args:Parameters<typeof fetch>)=>{const response=await original(...args);const target=String(args[0]);if(response.status===401&&user&&!target.includes('/auth/')&&!handling){handling=true;void expired().finally(()=>handling=false)}return response};
  const media=matchMedia('(prefers-color-scheme: dark)');const theme=()=>{if(user)applyTheme(user.theme)};media.addEventListener('change',theme);void state();return()=>{window.fetch=original;media.removeEventListener('change',theme)};
 });
</script>
{#if user&&!invitation}{#key user.id}<App {user} onlogout={logout} sessionEnded={expired} accountChanged={(a)=>{user=a;setAccount(a);applyTheme(a.theme)}}/>{/key}{:else}
<main class="auth-page"><section class="auth-card"><a class="auth-wordmark" href="/">Mosaune<span>LE GOÛT DES HISTOIRES</span></a>
{#if !ready}<p role="status">Connexion à votre serveur…</p>{:else}
<span class="eyebrow">VOTRE ESPACE, À VOUS</span><h1>{invitation?'Bienvenue chez vous.':setup?'Commençons ensemble.':recovery?'Retrouvez votre compte.':'Heureux de vous retrouver.'}</h1>
<p>{invitation?'Choisissez votre mot de passe pour activer votre compte.':setup?'Créez le premier administrateur. Votre collection et vos listes actuelles lui seront attribuées.':recovery?'Utilisez le code affiché dans la fenêtre du serveur pour choisir un nouveau mot de passe.':'Connectez-vous pour retrouver votre collection et vos écoutes.'}</p>
{#if user&&invitation}<p>Vous êtes connecté en tant que <strong>{user.name}</strong>. Déconnectez-vous pour activer ce compte, ou ouvrez le lien dans une fenêtre privée.</p><button class="primary" disabled={busy} onclick={logout}>Me déconnecter pour continuer</button>{:else}<form onsubmit={submit}>{#if !invitation}<label>Nom d’utilisateur<input required maxlength="48" autocomplete="username" bind:value={name}/></label>{/if}
{#if setup||recovery}<label>Code affiché par le serveur<input required autocomplete="off" bind:value={code}/></label><small>Le code est dans la fenêtre qui s’ouvre lorsque vous lancez Mosaune.</small>{/if}
<label>{invitation||setup||recovery?'Votre nouveau mot de passe':'Mot de passe'}<input type="password" required minlength={invitation||setup||recovery?12:undefined} maxlength="1024" autocomplete={invitation||setup||recovery?'new-password':'current-password'} bind:value={password}/></label>
{#if invitation||setup||recovery}<small>Au moins 12 caractères. Une longue phrase est facile à retenir.</small><label>Confirmer le mot de passe<input type="password" required autocomplete="new-password" bind:value={confirm}/></label>{/if}
{#if error}<p class="form-error" role="alert">{error}</p>{/if}<button class="primary" disabled={busy}>{busy?'Un instant…':invitation?'Activer mon compte':setup?'Créer mon espace':recovery?'Enregistrer et me connecter':'Se connecter'}</button></form>{/if}
{#if invitation}<button class="text-action" onclick={()=>{invitation=false;code='';password='';confirm='';}}>J’ai déjà un compte</button>{:else if !setup&&!recovery}<p class="auth-help">Première visite ? Ouvrez le lien d’invitation transmis par votre administrateur.<br/>Mot de passe oublié ? Demandez-lui de le réinitialiser.</p>{/if}
{/if}</section></main>{/if}
